#!/bin/sh
# First start of the bundle's database: the extensions the migrations use and
# the application role (no BYPASSRLS: row-level security backs every tenant
# predicate). Its password is generated by the gateway (hex, so it needs no
# quoting).
set -eu
psql -v ON_ERROR_STOP=1 --username postgres --dbname dns <<SQL
CREATE EXTENSION IF NOT EXISTS timescaledb;
CREATE EXTENSION IF NOT EXISTS citext;
CREATE ROLE dns_app LOGIN PASSWORD '${DNS_APP_PASSWORD}' NOBYPASSRLS;
GRANT CONNECT ON DATABASE dns TO dns_app;
SQL
